from harvests import load_harvests, ROWS
from summary import HarvestSummary

MEAN = sum(v for _, v in ROWS) / len(ROWS)


def test_mean_of_stored():
    assert abs(HarvestSummary(load_harvests()).mean_kilos() - MEAN) < 1e-9


def test_count_then_mean():
    s = HarvestSummary(load_harvests())
    assert s.count() == len(ROWS) and abs(s.mean_kilos() - MEAN) < 1e-9


def test_mean_twice():
    s = HarvestSummary(load_harvests())
    s.mean_kilos()
    assert abs(s.mean_kilos() - MEAN) < 1e-9


def test_list_input():
    assert abs(HarvestSummary(list(load_harvests())).mean_kilos() - MEAN) < 1e-9


def test_empty():
    assert HarvestSummary(iter([])).mean_kilos() == 0.0
